"""Stdio transport — spawns strata-mcp as a subprocess and communicates via MCP JSON-RPC."""

from __future__ import annotations

import shutil
from typing import Any

from mcp import ClientSession, StdioServerParameters
from mcp.client.stdio import stdio_client

from strata.exceptions import (
    StrataConnectionError,
    StrataNotFoundError,
    StrataProtocolError,
)
from strata.transport.base import Transport


class StdioTransport(Transport):
    """Spawns strata-mcp subprocess and communicates via stdin/stdout JSON-RPC."""

    def __init__(
        self,
        command: str = "npx",
        args: list[str] | None = None,
        env: dict[str, str] | None = None,
    ) -> None:
        self._command = command
        self._args = args if args is not None else ["strata-mcp"]
        self._env = env
        self._session: ClientSession | None = None
        self._context_stack: list[Any] = []

    async def connect(self) -> None:
        if self._session is not None:
            return

        # Verify binary exists
        if self._command == "npx":
            if not shutil.which("npx"):
                raise StrataNotFoundError(
                    "npx not found. Install Node.js (https://nodejs.org) "
                    "then run: npm install -g strata-mcp"
                )
        elif not shutil.which(self._command):
            raise StrataNotFoundError(f"Command not found: {self._command}")

        server_params = StdioServerParameters(
            command=self._command,
            args=self._args,
            env=self._env,
        )

        try:
            # Enter the stdio_client context manager
            cm = stdio_client(server_params)
            streams = await cm.__aenter__()
            self._context_stack.append(cm)

            # Enter the ClientSession context manager
            session = ClientSession(*streams)
            await session.__aenter__()
            self._context_stack.append(session)

            await session.initialize()
            self._session = session
        except Exception as exc:
            # Clean up on failure
            await self._cleanup_stack()
            raise StrataConnectionError(
                f"Failed to start strata-mcp subprocess: {exc}"
            ) from exc

    async def call_tool(self, name: str, arguments: dict[str, Any]) -> str:
        if self._session is None:
            raise StrataConnectionError("Not connected. Call connect() first.")

        try:
            result = await self._session.call_tool(name, arguments)
        except Exception as exc:
            raise StrataProtocolError(f"Tool call '{name}' failed: {exc}") from exc

        # Extract text from MCP result
        parts: list[str] = []
        for content in result.content:
            if hasattr(content, "text"):
                parts.append(content.text)
        if not parts:
            raise StrataProtocolError(f"Empty response from tool '{name}'", raw_response=str(result))
        return "\n".join(parts)

    async def close(self) -> None:
        self._session = None
        await self._cleanup_stack()

    async def _cleanup_stack(self) -> None:
        while self._context_stack:
            cm = self._context_stack.pop()
            try:
                await cm.__aexit__(None, None, None)
            except Exception:
                pass
